<?php
$field=function(string $key,string $label,string $type='text',string $default='') use($error): void { $val=$error!==''?($_POST[$key]??setting($key,$default)):setting($key,$default); ?><label><?= e($label) ?><?php if($type==='textarea'): ?><textarea name="<?= e($key) ?>" rows="3"><?= e($val) ?></textarea><?php else: ?><input name="<?= e($key) ?>" type="<?= e($type) ?>" value="<?= e($val) ?>"><?php endif ?></label><?php };
$secretField=function(string $key,string $label): void { ?><label><?= e($label) ?><input name="<?= e($key) ?>" type="password" autocomplete="new-password" placeholder="<?= setting($key)?'Guardado · Dejar vacío para conservar':'Sin configurar' ?>"></label><?php if(setting($key)): ?><label class="check"><input type="checkbox" name="clear_<?= e($key) ?>"> Eliminar credencial guardada</label><?php endif ?><?php };
?>
<section class="container section"><p class="eyebrow">TU TIENDA, A TU MANERA</p><div class="section-heading"><h1>Configuración.</h1><a class="btn secondary small" href="/admin/configuracion/logs">Ver errores de PHP ↗</a></div><?php if($error): ?><div class="alert" role="alert"><?= e($error) ?></div><?php endif ?><form method="post" enctype="multipart/form-data" class="settings-form"><?= csrf() ?><div class="form-panel"><h2>01. Identidad y presentación</h2><?php $field('brand','Nombre comercial','text','FiloLux'); $field('hero_title','Título principal'); $field('hero_text','Texto de portada','textarea'); $field('about','Sobre el emprendimiento','textarea') ?><label>Logo (JPG, PNG o WebP)<input type="file" name="logo" accept="image/jpeg,image/png,image/webp"></label><?php if(setting('logo')): ?><img class="logo-preview" src="/<?= e(setting('logo')) ?>" alt="Logo actual"><label class="check"><input name="clear_logo" type="checkbox"> Quitar logo</label><?php endif ?></div><div class="form-panel"><h2>02. Contacto y entregas</h2><div class="form-grid"><?php $field('whatsapp','WhatsApp con código de país (ej. 54911…)'); $field('contact_email','Correo público','email'); $field('instagram','Instagram (URL completa)','url'); $field('facebook','Facebook (URL completa)','url'); $field('contact_address','Dirección pública'); $field('hours','Horarios') ?></div><?php $field('pickup','Instrucciones para el retiro','textarea') ?><label>Precio único de envío (ARS)<input name="shipping_price" inputmode="decimal" value="<?= e($error?($_POST['shipping_price']??'0'):number_format((int)setting('shipping_price','0')/100,2,'.','')) ?>" required></label><p class="microcopy">Ingresá el importe sin separadores de miles. El retiro siempre es gratuito.</p></div><div class="form-panel"><h2>03. Mercado Pago</h2><p>Los pagos requieren HTTPS, Access Token y secreto de webhook del entorno elegido. Las credenciales se guardan cifradas y nunca se muestran completas.</p><label>Entorno activo<select name="mp_mode"><option value="test" <?= setting('mp_mode','test')==='test'?'selected':'' ?>>Pruebas</option><option value="production" <?= setting('mp_mode')==='production'?'selected':'' ?>>Producción (cobros reales)</option></select></label><div class="form-grid"><div><h3>Pruebas</h3><?php $secretField('mp_test_token','Access Token de pruebas'); $secretField('mp_test_webhook','Secreto de webhook de pruebas') ?></div><div><h3>Producción</h3><?php $secretField('mp_production_token','Access Token de producción'); $secretField('mp_production_webhook','Secreto de webhook de producción') ?></div></div><label>URL de webhook (evento: pagos)<input value="<?= e(url('/webhook/mercadopago')) ?>" readonly></label><p class="microcopy">Creá tu aplicación en Mercado Pago Developers y configurá esta URL en Notificaciones Webhooks para el evento de pagos. Checkout Pro por redirección utiliza el Access Token; no necesita Public Key en el navegador. Conservar credenciales permite verificar pedidos del entorno anterior.</p></div><div class="form-panel"><h2>04. Correo SMTP</h2><p>Permite recuperar contraseñas y enviar avisos de pedidos y pagos. Sin configurar, la tienda funciona sin enviar correos.</p><div class="form-grid"><?php $field('smtp_host','Servidor SMTP'); $field('smtp_port','Puerto','number','587'); $field('smtp_user','Usuario SMTP'); $field('smtp_from','Correo remitente','email') ?></div><label>Seguridad<select name="smtp_security"><option value="tls" <?= setting('smtp_security','tls')==='tls'?'selected':'' ?>>STARTTLS (habitualmente puerto 587)</option><option value="ssl" <?= setting('smtp_security')==='ssl'?'selected':'' ?>>TLS implícito (habitualmente puerto 465)</option></select></label><?php $secretField('smtp_password','Contraseña SMTP') ?></div><div class="settings-actions"><button class="btn">Guardar configuración ↗</button></div></form><form method="post" class="smtp-test"><?= csrf() ?><button class="btn secondary" name="test_mail" value="1">Enviar correo de prueba</button><p class="microcopy">Usa la configuración guardada y envía a <?= e(user()['email']) ?>.</p></form></section>
